'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
Promise.all([fetch('data.json').then(r=>r.json()),fetch('assets/photos.json').then(r=>r.json()).catch(()=>[])]).then(([d,photos])=>{
 document.getElementById('references-list').innerHTML=Object.values(d.sources).map(s=>`<div class="source-entry"><span class="source-type">${esc(s.kind)}</span><h3>${esc(s.title)}</h3><p class="publisher">${esc(s.publisher)}</p><p>${esc(s.note)}</p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open this source</a></div>`).join('');
 document.getElementById('image-list').innerHTML=photos.map(p=>`<figure class="image-credit"><img src="${esc(p.path)}" width="${p.width}" height="${p.height}" alt="${esc(p.alt)}" loading="lazy"><figcaption><p><strong>${esc(p.caption)}</strong></p><p>${esc(p.credit)}</p><p>${esc(p.license)}</p><p><a href="${esc(p.sourcePage)}" target="_blank" rel="noopener noreferrer">Source and reuse record</a> · <a href="${esc(p.archivalSource)}" target="_blank" rel="noopener noreferrer">Vivekananda House archival description</a></p></figcaption></figure>`).join('');
 document.getElementById('dataset-stats').textContent=`${d.events.length} events across ${new Set(d.events.map(e=>e.location)).size} places, organised into ${d.journeys.length} periods. ${d.routes.length} separately documented or explicitly illustrative connections.`;
}).catch(()=>{document.getElementById('references-list').innerHTML='<p>The source catalogue could not load. Reload the page to try again.</p>'});
